#!/bin/bash
# Generated by v32c++ from the source's own cart hints and command line. Edit
# the source (or use --no-build-scripts and keep a hand-written script)
# rather than this file: it is rewritten on every v32c++ run.

abort_build()
{
    echo
    echo BUILD FAILED
    exit 1
}

# the tools this build needs
need_tool()
{
    command -v "$1" >/dev/null 2>&1 || { echo "ERROR: $1 is needed to build, but was not found in PATH"; abort_build; }
}

need_tool v32c++
need_tool compile
need_tool assemble
need_tool packrom
need_tool png2vircon
need_tool wav2vircon

# the optimizer is optional: without it only the regular build is made
HAVE_OPT=0
if command -v v32opt >/dev/null 2>&1; then
    HAVE_OPT=1
else
    echo "note: v32opt not found in PATH -- skipping the optimized (Opt) build"
fi

# create the output folders, since the development tools will not
mkdir -p bin
mkdir -p obj

echo
echo Transpile to Vircon32 C
echo --------------------------
v32c++ -b --no-build-scripts -o obj/debuggerBIOS-ng.c debuggerBIOS-ng.cpp || abort_build

echo
echo Compile the C code
echo --------------------------
compile -b obj/debuggerBIOS-ng.c -o obj/debuggerBIOS-ng.asm || abort_build
if [ "$HAVE_OPT" = 1 ]; then
    v32opt -O3 obj/debuggerBIOS-ng.asm -o obj/debuggerBIOS-ngOpt.asm || abort_build
fi

echo
echo Assemble the ASM code
echo --------------------------
assemble -b obj/debuggerBIOS-ng.asm -o obj/debuggerBIOS-ng.vbin || abort_build
if [ "$HAVE_OPT" = 1 ]; then
    assemble -b obj/debuggerBIOS-ngOpt.asm -o obj/debuggerBIOS-ngOpt.vbin || abort_build
fi

echo
echo Convert the PNG textures
echo --------------------------
png2vircon assets/BiosTexture.png -o obj/BiosTexture.vtex || abort_build

echo
echo Convert the WAV sounds
echo --------------------------
wav2vircon assets/BiosSound.wav -o obj/BiosSound.vsnd || abort_build

echo
echo Pack the ROM
echo --------------------------
packrom obj/debuggerBIOS-ng.xml -o bin/debuggerBIOS-ng.v32 || abort_build
if [ "$HAVE_OPT" = 1 ]; then
    packrom obj/debuggerBIOS-ngOpt.xml -o bin/debuggerBIOS-ngOpt.v32 || abort_build
fi

echo
echo BUILD SUCCESSFUL
